package com.registration.servlet;
import com.registration.dao.StudentDAO;import com.registration.model.Student;import javax.servlet.http.*;import javax.servlet.*;import java.io.*;import java.net.URLEncoder;import java.sql.SQLException;import java.time.*;
public class RegisterServlet extends HttpServlet{private static final long serialVersionUID=1L;private final StudentDAO dao=new StudentDAO();protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException{q.setCharacterEncoding("UTF-8");String n=t(q,"fullName"),e=t(q,"email"),p=t(q,"phone"),g=t(q,"gender"),c=t(q,"course"),d=t(q,"dateOfBirth"),a=t(q,"address");String er=v(n,e,p,g,c,d,a);if(er!=null){err(q,r,er);return;}try{LocalDate dob=LocalDate.parse(d);if(dao.insertStudent(new Student(n,e,p,g,c,dob,a)))r.sendRedirect(q.getContextPath()+"/success.html");else err(q,r,"Registration could not be completed.");}catch(Exception x){x.printStackTrace();err(q,r,x instanceof SQLException&&((SQLException)x).getErrorCode()==1062?"This email address is already registered.":"Database error. Check MySQL setup and Connector/J.");}}private String v(String n,String e,String p,String g,String c,String d,String a){if(n.isEmpty()||e.isEmpty()||p.isEmpty()||g.isEmpty()||c.isEmpty()||d.isEmpty()||a.isEmpty())return "All fields are required.";if(!n.matches("[A-Za-z .'-]{2,100}"))return "Invalid full name.";if(!e.matches("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\\\.[A-Za-z]{2,}$"))return "Enter a valid email address.";if(!p.matches("[0-9]{10,15}"))return "Phone number must contain 10 to 15 digits.";try{LocalDate dob=LocalDate.parse(d);if(dob.isAfter(LocalDate.now()))return "Date of birth cannot be in the future.";int age=Period.between(dob,LocalDate.now()).getYears();if(age<10||age>100)return "Enter a realistic date of birth.";}catch(Exception x){return "Invalid date of birth.";}if(a.length()>255)return "Address must not exceed 255 characters.";return null;}private String t(HttpServletRequest r,String k){String x=r.getParameter(k);return x==null?"":x.trim();}private void err(HttpServletRequest r,HttpServletResponse s,String m)throws IOException{s.sendRedirect(r.getContextPath()+"/error.html?message="+URLEncoder.encode(m,"UTF-8"));}}